import React, { useState } from "react";
import { Text, View } from "react-native";
import { TemplateShell, SectionHeading } from "./template-shell";
import { useSkeuo } from "../theme";
import { SkeuoCard } from "../skeuo-card";
import { SkeuoInput } from "../skeuo-input";
import { SkeuoButton } from "../skeuo-button";
import { SummaryCard } from "../blocks/summary-card";
import { ActivityChart } from "../blocks/activity-chart";
import { HabitList } from "../blocks/habit-list";
import { SkeuoPhotoCarousel } from "../skeuo-photo-carousel";
const items = [
  { value: "home", label: "Today" },
  { value: "activity", label: "Activity" },
  { value: "goals", label: "Goals" },
  { value: "profile", label: "Profile" },
];
export function DaybookTemplate() {
  const { colors: c } = useSkeuo();
  const [tab, setTab] = useState("home");
  const [name, setName] = useState("Alex");
  const [period, setPeriod] = useState(false);
  const [done,setDone] = useState(["A little movement"]);
  return (
    <TemplateShell
      name="daybook"
      subtitle="A RECORD OF THE EVERYDAY"
      items={items}
      value={tab}
      onValueChange={setTab}
      variant="pill"
    >
      {tab === "home" ? (
        <>
          <SectionHeading
            title={`A good day, ${name}.`}
            detail="Make a little space for the things you love."
          />
          <SummaryCard
            label="Time well spent"
            value="24.5 hrs"
            detail="4.5 hours more than last week"
          />
          <SkeuoCard>
            <Text style={{ color: c.ink, fontSize: 16, fontWeight: "600" }}>
              This week&apos;s rhythm
            </Text>
            <ActivityChart />
          </SkeuoCard>
          <SkeuoPhotoCarousel
            items={[
              {
                uri: "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?w=640&q=80",
                title: "Somewhere quiet",
                caption: "A small collection of places worth remembering.",
              },
              {
                uri: "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=640&q=80",
                title: "Take the long way home",
              },
            ]}
          />
        </>
      ) : tab === "activity" ? (
        <>
          <SectionHeading
            title="Look how far."
            detail="Illustrative activity, at your own pace."
          />
          <View style={{ flexDirection: "row", gap: 10 }}>
            <SkeuoButton onPress={() => setPeriod(false)}>
              This week
            </SkeuoButton>
            <SkeuoButton onPress={() => setPeriod(true)}>Last week</SkeuoButton>
          </View>
          <SummaryCard
            label={period ? "Last week" : "This week"}
            value={period ? "20.0 hrs" : "24.5 hrs"}
            detail="Reading, walking and making"
          />
          <SkeuoCard>
            <ActivityChart
              values={period ? [20, 40, 25, 66, 35, 55, 30] : undefined}
            />
          </SkeuoCard>
        </>
      ) : tab === "goals" ? (
        <>
          <SectionHeading
            title="Things worth doing."
            detail="One small promise at a time."
          />
          <SkeuoCard>
            <HabitList value={done} onValueChange={setDone}/>
          </SkeuoCard>
        </>
      ) : (
        <>
          <SectionHeading title="Hello, you." />
          <SkeuoCard>
            <SkeuoInput label="Your name" value={name} onChangeText={setName} />
            <Text style={{ color: c.muted, lineHeight: 20 }}>
              Your personal activity starter. All sample data is fictional and
              changes reset when the demo restarts.
            </Text>
          </SkeuoCard>
        </>
      )}
    </TemplateShell>
  );
}

import React from "react";
import { ScrollView, Text, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useSkeuo } from "../theme";
import {
  SkeuoBottomBar,
  type BottomBarItem,
  type BottomBarVariant,
} from "../skeuo-bottom-bar";
export function TemplateShell({
  name,
  subtitle,
  children,
  items,
  value,
  onValueChange,
  variant = "dock",
  action,
}: {
  name: string;
  subtitle?: string;
  children: React.ReactNode;
  items: BottomBarItem[];
  value: string;
  onValueChange: (value: string) => void;
  variant?: BottomBarVariant;
  action?: React.ReactNode;
}) {
  const { colors: c } = useSkeuo();
  const insets = useSafeAreaInsets();
  return (
    <View
      style={{ flex: 1, backgroundColor: c.background, paddingTop: insets.top }}
    >
      <View
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "center",
          paddingHorizontal: 22,
          paddingTop: subtitle ? 18 : 12,
          paddingBottom: subtitle ? 18 : 16,
        }}
      >
        <View style={{ gap: 3 }}>
          <Text
            style={{
              color: c.ink,
              fontSize: 20,
              fontWeight: "700",
              letterSpacing: -0.6,
            }}
          >
            {name}
            <Text style={{ color: c.accent }}>.</Text>
          </Text>
          {subtitle && (
            <Text style={{ color: c.muted, fontSize: 10 }}>{subtitle}</Text>
          )}
        </View>
        {action ?? (
          <View
            style={{
              height: 34,
              width: 34,
              borderRadius: 17,
              backgroundColor: c.well,
              borderWidth: 1,
              borderColor: c.edge,
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Text style={{ color: c.muted, fontSize: 11 }}>AM</Text>
          </View>
        )}
      </View>
      <ScrollView
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={{
          paddingHorizontal: 22,
          paddingBottom: 24,
          gap: subtitle ? 24 : 18,
        }}
      >
        {children}
      </ScrollView>
      <SkeuoBottomBar
        items={items}
        value={value}
        onValueChange={onValueChange}
        variant={variant}
        bottomInset={insets.bottom}
      />
    </View>
  );
}
export function SectionHeading({
  title,
  detail,
}: {
  title: string;
  detail?: string;
}) {
  const { colors: c } = useSkeuo();
  return (
    <View style={{ gap: 7 }}>
      <Text
        accessibilityRole="header"
        style={{
          fontSize: 29,
          fontWeight: "500",
          color: c.ink,
          letterSpacing: -1,
        }}
      >
        {title}
      </Text>
      {detail && (
        <Text style={{ color: c.muted, fontSize: 13, lineHeight: 20 }}>
          {detail}
        </Text>
      )}
    </View>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}

import React from "react";
import { Pressable, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { useFeedback, useSkeuo } from "./theme";
import { SkeuoGlyph } from "./icons";
import { SkeuoDockBar, type DockBarProps } from "./skeuo-dock-bar";

export type { BottomBarItem } from "./skeuo-dock-bar";
export type BottomBarVariant = "dock" | "keys" | "rail" | "pill";
export function SkeuoBottomBar({
  items,
  value,
  onValueChange,
  variant = "dock",
  bottomInset = 0,
}: DockBarProps & { variant?: BottomBarVariant }) {
  if (variant === "dock") {
    return <SkeuoDockBar {...{ items, value, onValueChange, bottomInset }} />;
  }
  return <LabeledBottomBar {...{ items, value, onValueChange, variant, bottomInset }} />;
}

function LabeledBottomBar({
  items,
  value,
  onValueChange,
  variant,
  bottomInset = 0,
}: DockBarProps & { variant: Exclude<BottomBarVariant, "dock"> }) {
  const { colors: c } = useSkeuo();
  const feedback = useFeedback();
  return (
    <View
      accessibilityRole="tablist"
      accessibilityLabel="Bottom navigation"
      style={{
        paddingBottom: Math.max(8, bottomInset),
        paddingTop: 12,
        paddingHorizontal: variant === "rail" ? 0 : 12,
        backgroundColor: c.background,
      }}
    >
      <View
        style={{
          flexDirection: "row",
          gap: variant === "keys" ? 8 : 2,
          padding: variant === "pill" ? 5 : 0,
          borderWidth: variant === "pill" ? 1 : 0,
          borderColor: c.edge,
          borderRadius: variant === "pill" ? 32 : 16,
          backgroundColor: variant === "keys" ? c.background : c.well,
        }}
      >
        {items.map((item) => {
          const active = item.value === value;
          return (
            <Pressable
              key={item.value}
              accessibilityRole="tab"
              aria-selected={active}
              aria-disabled={!!item.disabled}
              accessibilityLabel={item.label}
              accessibilityState={{
                selected: active,
                disabled: !!item.disabled,
              }}
              disabled={item.disabled}
              onPress={() => {
                feedback();
                onValueChange(item.value);
              }}
              style={({ pressed }) => ({
                flex: 1,
                minHeight: 60,
                borderRadius: variant === "pill" ? 26 : 10,
                borderWidth: variant === "keys" ? 1 : 0,
                borderBottomWidth:
                  variant === "keys"
                    ? pressed
                      ? 1
                      : 4
                    : active && variant === "rail"
                      ? 3
                      : 1,
                borderColor: active && variant === "rail" ? c.accent : c.edge,
                backgroundColor: active
                  ? c.raised
                  : variant === "keys"
                    ? c.surface
                    : "transparent",
                opacity: item.disabled ? 0.4 : 1,
                transform: [{ translateY: pressed ? 2 : 0 }],
                overflow: "hidden",
              })}
            >
              <LinearGradient
                colors={active ? [c.raised, c.surface] : [c.well, c.well]}
                style={{
                  flex: 1,
                  alignItems: "center",
                  justifyContent: "center",
                  paddingVertical: 8,
                  gap: 3,
                }}
              >
                {item.icon ?? (
                  <SkeuoGlyph
                    name={item.value}
                    color={active ? c.accent : c.muted}
                  />
                )}
                <Text
                  numberOfLines={1}
                  style={{
                    fontSize: 10,
                    fontWeight: active ? "700" : "500",
                    color: active ? c.ink : c.muted,
                  }}
                >
                  {item.label}
                </Text>
              </LinearGradient>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

import { Text } from "react-native";
/** Simple line symbols keep the portable controls independent of an icon package. Hosts may pass their own icons. */
export function SkeuoGlyph({
  name,
  color = "#686863",
  size = 21,
}: {
  name: string;
  color?: string;
  size?: number;
}) {
  const symbols: Record<string, string> = {
    home: "⌂",
    transactions: "⇄",
    analysis: "▥",
    profile: "○",
    focus: "◷",
    habits: "✓",
    journal: "≡",
    settings: "⚙",
    activity: "↗",
    goals: "◎",
    saved: "▱",
    add: "+",
    arrow: "↗",
    back: "‹",
    next: "›",
    play: "▶",
    pause: "Ⅱ",
    sound: "♪",
  };
  return (
    <Text
      accessible={false}
      style={{
        color,
        fontSize: size,
        lineHeight: size + 4,
        textAlign: "center",
