}

import React from "react";
import { Text, TextInput, View, TextInputProps } from "react-native";
import { useSkeuo } from "./theme";
import { styles } from "./styles";
import { SkeuoText } from "./skeuo-text";
export function SkeuoInput({
  label,
  error,
  style,
  ...props
}: TextInputProps & { label: string; error?: string }) {
  const { colors } = useSkeuo();
  const [focused, setFocused] = React.useState(false);
  return (
    <View style={styles.stack}>
      <SkeuoText>{label}</SkeuoText>
      <TextInput
        {...props}
        accessibilityLabel={props.accessibilityLabel ?? label}
        placeholderTextColor={colors.muted}
        onFocus={(e) => {
          setFocused(true);
          props.onFocus?.(e);
        }}
        onBlur={(e) => {
          setFocused(false);
          props.onBlur?.(e);
        }}
        style={[
          styles.input,
          {
            color: colors.ink,
            backgroundColor: colors.well,
            borderColor: focused ? colors.accent : colors.edge,
          },
          style,
        ]}
      />
      {error && (
        <Text accessibilityRole="alert" style={{ color: colors.ink }}>
          Error: {error}
        </Text>
      )}
    </View>
  );
}

import React from "react";
import { Text } from "react-native";
import { useSkeuo } from "./theme";
export function SkeuoText({
  children,
  muted = false,
}: {
  children: React.ReactNode;
  muted?: boolean;
}) {
  const { colors } = useSkeuo();
  return (
    <Text
      style={{
        color: muted ? colors.muted : colors.ink,
        fontSize: 16,
        lineHeight: 24,
      }}
    >
      {children}
    </Text>
  );
}

import { StyleSheet } from "react-native";
import React from "react";
import { Button } from "@/components/ui/button";
import { Text } from "@/components/ui/text";
import { LinearGradient } from "expo-linear-gradient";
import { useSkeuo, useFeedback } from "./theme";
import { styles } from "./styles";
import type { ButtonProps } from "./types";
export function SkeuoButton({
  children,
  onPress,
  disabled = false,
  variant = "default",
  accessibilityLabel,
}: ButtonProps) {
  const { colors } = useSkeuo();
  const feedback = useFeedback();
  const accent = variant === "accent";
  const [focused, setFocused] = React.useState(false);
  const [pressed, setPressed] = React.useState(false);
  return (
    <Button
      variant="ghost"
      className="p-0 h-auto"
      onPressIn={() => setPressed(true)}
      onPressOut={() => setPressed(false)}
      onFocus={() => setFocused(true)}
      onBlur={() => setFocused(false)}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      accessibilityState={{ disabled }}
      disabled={disabled}
      onPress={() => {
        feedback();
        onPress();
      }}
      style={StyleSheet.flatten([
        styles.button,
        {
          opacity: disabled ? 0.45 : 1,
          borderColor: focused ? colors.accent : colors.edge,
          backgroundColor: colors.base,
          borderBottomWidth: pressed ? 1 : 4,
          transform: [{ translateY: pressed ? 3 : 0 }],
        },
      ])}
    >
      <LinearGradient
        colors={
          accent
            ? [colors.accent, colors.accent]
